// Built by scripts/build.js from workflows/code/instagram-comment-reply/plan-comment.js and src/. Edit those files, not this node.

const CONFIG = Object.freeze({
  "COMMENT_REPLY_CAP_PER_HOUR": 20,
  "PRICE_LIST_URL": "https://example.com/paket-dan-harga"
});

const __modules = {
  'comment-rules': function (module, exports, require) {
'use strict';

const { buildClaimRow } = require('./canonical');
const { buildInstagramPrivateReply, buildInstagramPublicReply } = require('./senders');
const { toMysqlDateTime } = require('./text');

// Order matters: a gambling-spam comment that also says "harga" must be treated as spam.
const RULES = [
  {
    category: 'spam',
    patterns: [
      /https?:\/\/|www\.|bit\.ly|\b[a-z0-9-]+\.(com|net|xyz|site|online|link)\b/,
      /\b(slot|gacor|maxwin|togel|judi|depo|deposit|jackpot)\b/,
      /\b(follow back|follback|f4f|cek bio|check my bio|dm for collab)\b/,
    ],
  },
  {
    category: 'insult',
    patterns: [
      /\b(anjing|anjg|bangsat|bajingan|brengsek|goblok|goblog|tolol|kampret|idiot|stupid)\b/,
    ],
  },
  {
    category: 'price_inquiry',
    patterns: [
      /\b(harga|hrg|brp|berapaan|biaya|tarif|pricelist|price ?list|price|how much)\b/,
      /\b(info|minta|cek) (harga|pl|pricelist)\b/,
    ],
  },
];

// Lowercase, fold Unicode look-alikes and collapse stretched letters ("hargaaa", "tololll").
function normalizeForMatching(text) {
  return text
    .normalize('NFKC')
    .toLowerCase()
    .replace(/(\p{L})\1{2,}/gu, '$1')
    .replace(/\s+/g, ' ');
}

function classifyComment(text) {
  const normalized = normalizeForMatching(text);
  for (const rule of RULES) {
    const pattern = rule.patterns.find((candidate) => candidate.test(normalized));
    if (pattern) return { category: rule.category, matched: pattern.source };
  }
  return { category: 'other', matched: null };
}

function hourWindowStart(date) {
  const start = new Date(date);
  start.setUTCMinutes(0, 0, 0);
  return toMysqlDateTime(start).slice(0, 19);
}

function renderReplies(comment, priceListUrl) {
  const handle = comment.username ? `@${comment.username}` : 'kak';
  return {
    public: `Halo ${handle}, info harga sudah kami kirim lewat DM ya. Silakan cek inbox.`,
    private: [
      `Halo ${comment.username ? `kak ${comment.username}` : 'kak'}, terima kasih sudah bertanya.`,
      `Daftar paket dan harga lengkap bisa dilihat di sini: ${priceListUrl}`,
      'Balas pesan ini kalau ada yang ingin ditanyakan, tim kami siap membantu.',
    ].join('\n'),
  };
}

// Everything the comment workflow needs for one comment: the rule outcome, the message_log
// claim row, the rate-limit bucket and (for price questions) both reply payloads.
function planComment(comment, { priceListUrl, hourlyCap, now = new Date() }) {
  if (!Number.isInteger(hourlyCap) || hourlyCap < 1) {
    throw new Error('hourlyCap must be a positive integer');
  }
  const { category, matched } = classifyComment(comment.text);
  const plan = {
    comment_id: comment.comment_id,
    category,
    matched,
    reasons: [category === 'other' ? 'no_rule_matched' : `rule_${category}`],
    claim: buildClaimRow({
      channel: 'instagram_comment',
      external_message_id: comment.comment_id,
      customer_id: comment.from_id,
      customer_name: comment.username,
      text: comment.text,
      received_at: comment.received_at,
    }),
    rate_limit: {
      scope_key: `instagram:${comment.account_id}`,
      window_start: hourWindowStart(now),
      cap: hourlyCap,
    },
    public_reply: null,
    private_reply: null,
  };

  if (category === 'price_inquiry') {
    const texts = renderReplies(comment, priceListUrl);
    plan.public_reply = {
      comment_id: comment.comment_id,
      body: buildInstagramPublicReply(texts.public),
    };
    plan.private_reply = {
      account_id: comment.account_id,
      body: buildInstagramPrivateReply(comment.comment_id, texts.private),
    };
  }
  return plan;
}

module.exports = { classifyComment, planComment };
  },
  'canonical': function (module, exports, require) {
'use strict';

const { truncate, toMysqlDateTime } = require('./text');

const CHANNELS = ['whatsapp', 'instagram', 'telegram'];
const MAX_EXTERNAL_ID_LENGTH = 255;
const MAX_CUSTOMER_ID_LENGTH = 128;
const MAX_CUSTOMER_NAME_LENGTH = 120;
const MAX_TEXT_LENGTH = 4000;
const TEXT_PREVIEW_LENGTH = 500;

function requireString(message, field, maxLength) {
  const value = message[field];
  if (typeof value !== 'string' || value.length === 0 || value.length > maxLength) {
    throw new Error(`Canonical message field "${field}" must be a string of 1-${maxLength} chars`);
  }
}

// Guards the contract between the normalisers and the rest of the pipeline, so a normaliser
// bug fails here with a clear message instead of as a 400 from the AI service.
function assertCanonicalMessage(message) {
  if (!message || typeof message !== 'object') throw new Error('Canonical message is missing');
  if (!CHANNELS.includes(message.channel)) {
    throw new Error(`Unknown channel "${String(message.channel)}"`);
  }
  requireString(message, 'external_message_id', MAX_EXTERNAL_ID_LENGTH);
  requireString(message, 'customer_id', MAX_CUSTOMER_ID_LENGTH);
  requireString(message, 'text', MAX_TEXT_LENGTH);
  if (Number.isNaN(Date.parse(message.received_at))) {
    throw new Error('Canonical message field "received_at" must be an ISO-8601 timestamp');
  }
  if (message.customer_name !== null && typeof message.customer_name !== 'string') {
    throw new Error('Canonical message field "customer_name" must be a string or null');
  }
  if (!message.reply_target || typeof message.reply_target !== 'object') {
    throw new Error('Canonical message field "reply_target" is required');
  }
  return message;
}

// Request body for ai-support-service POST /v1/messages.
function buildAiRequest(message) {
  assertCanonicalMessage(message);
  const request = {
    channel: message.channel,
    external_message_id: message.external_message_id,
    customer_id: message.customer_id,
    text: message.text,
    received_at: message.received_at,
  };
  const name = message.customer_name ? message.customer_name.trim() : '';
  if (name) request.customer_name = truncate(name, MAX_CUSTOMER_NAME_LENGTH);
  return request;
}

// First write to message_log. The UNIQUE (channel, external_message_id) key turns this
// insert into the de-duplication step for webhook redeliveries.
function buildClaimRow(message) {
  return {
    channel: message.channel,
    external_message_id: message.external_message_id,
    customer_id: message.customer_id,
    customer_name: message.customer_name
      ? truncate(message.customer_name, MAX_CUSTOMER_NAME_LENGTH)
      : null,
    text_preview: truncate(message.text, TEXT_PREVIEW_LENGTH),
    received_at: toMysqlDateTime(message.received_at),
  };
}

module.exports = { CHANNELS, assertCanonicalMessage, buildAiRequest, buildClaimRow };
